 const watches=sortedDefault(allResults.filter(x=>x.category!=='ETF'&&candidateTier(x)==='watch')).slice(0,3);
 const items=(buys.length?buys.slice(0,3):watches);
 if(!items.length){headline.className='buy-focus-headline focus-none';headline.textContent='현재는 후보도, 조건에 가까운 관심후보도 없습니다.';return}
