 items.forEach((x,i)=>{const isBuy=candidateTier(x)==='buy',d=document.createElement('div'),v=beginnerVerdict(x),s=sessionForItem(x);d.className=`etf-focus-item ${isBuy?'etf-buy':'etf-watch'}`;d.innerHTML=`<div><b>${i+1}. ${escapeText(x.name)}</b><span>${Number(x.opportunity_score||0).toFixed(0)}점</span></div><strong>${escapeText(v.text)}</strong><small>${escapeText(s.label)} · 진입 ${fmt(x.entry_krw)}원 · 손익비 1:${Number(x.rrr||0).toFixed(2)} · ${escapeText(x.buy_time||'-')}</small>`;box.appendChild(d)})
