 const valid=allResults.filter(x=>x.ok),individual=valid.filter(x=>x.category!=='ETF'),greens=individual.filter(x=>beginnerVerdict(x).level==='green'),openGreens=greens.filter(immediateAllowed),yellows=individual.filter(x=>beginnerVerdict(x).level==='yellow'),etfGreens=valid.filter(x=>x.category==='ETF'&&beginnerVerdict(x).level==='green'),openEtf=etfGreens.filter(immediateAllowed);const card=$('answerCard');card.classList.remove('answer-yes','answer-wait','answer-no');
