function sortResults(items){const m=$('sortBy').value,copy=[...items];if(m==='momentum')copy.sort((a,b)=>Number(b.momentum||0)-Number(a.momentum||0));else if(m==='rrr')copy.sort((a,b)=>Number(b.rrr||0)-Number(a.rrr||0));else if(m==='name')copy.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'ko'));else return sortedDefault(copy);return copy}
function renderCards(){const frag=document.createDocumentFragment(),items=sortResults(allResults);items.forEach((x,i)=>{const node=renderCard(x);const card=node.querySelector('.stock-card');card.dataset.rank=String(i+1);frag.appendChild(node)});$('cards').innerHTML='';$('cards').appendChild(frag);applyFilter()}
function applyFilter(){const q=$('search').value.trim().toLowerCase();let visibleIndex=0;document.querySelectorAll('.stock-card').forEach(card=>{const qok=!q||card.dataset.search.includes(q);let fok=true;if(activeFilter==='KR')fok=card.dataset.category==='KR';else if(activeFilter==='US')fok=card.dataset.category==='US';else if(activeFilter==='ETF')fok=card.dataset.category==='ETF';else if(activeFilter==='HELD')fok=card.dataset.held==='1';else if(activeFilter==='BUY')fok=card.dataset.buy==='1';else if(activeFilter==='LONG')fok=card.dataset.long==='1';const sok=currentSector==='ALL'||card.dataset.sector===currentSector;const base=qok&&fok&&sok;if(base)visibleIndex++;const limitOk=showAll||q||activeFilter!=='ALL'||visibleIndex<=3;card.style.display=(base&&limitOk)?'block':'none'});$('toggleAllBtn').textContent=showAll?'TOP 3만 보기':'전체 보기'}
$('search').addEventListener('input',applyFilter);$('sectorFilter').addEventListener('change',()=>{currentSector=$('sectorFilter').value;showAll=true;applyFilter()});
$('sortBy').addEventListener('change',renderCards);$('toggleAllBtn').addEventListener('click',()=>{showAll=!showAll;applyFilter()});document.querySelectorAll('.chip').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');activeFilter=btn.dataset.filter;applyFilter()}));
function renderTopPick(){const greens=sortedDefault(allResults.filter(x=>x.ok&&x.category!=='ETF'&&beginnerVerdict(x).level==='green'&&immediateAllowed(x))),best=greens[0];if(!best){$('topPick').hidden=true;$('noBuyCard').hidden=false;const yellow=allResults.filter(x=>x.ok&&beginnerVerdict(x).level==='yellow').length;$('noBuyReason').textContent=yellow?`즉시 매수 후보는 0개입니다. 조건에 가까운 대기 후보 ${yellow}개를 아래에서 비교하세요.`:'즉시 매수 후보는 0개입니다. 아래 실전 우선순위에서 관심후보를 확인하세요.';return}$('noBuyCard').hidden=true;$('topPick').hidden=false;const v=beginnerVerdict(best);$('topPick').className='verdict-card card verdict-card-green';$('topPickAction').textContent=v.text;$('topPickName').textContent=`${best.name} (${best.code})`;$('topPickReason').textContent=`${best.tech} · ${best.grade}급 · 모멘텀 ${best.momentum}점 · 손익비 1:${best.rrr}`;$('topPickReasons').innerHTML=v.why.map(x=>`<div>✓ ${escapeText(x)}</div>`).join('');$('topPickEntry').textContent=`${fmt(best.entry_krw)}원`;$('topPickTarget').textContent=`${fmt(best.target1_krw)}원`;$('topPickStop').textContent=`${fmt(best.stop1_krw)}원`;$('topPickQty').textContent=best.qty>0?`${best.qty}주`:'0주';$('topPickBuyTime').textContent=`${best.buy_time||'-'} · ${best.time_zone_note||''}`;$('topPickSellPlan').textContent=best.sell_plan||'-';$('topPickRiskNote').textContent=`🧮 ${best.sizing_limiter||'위험기반 수량'} · 예상 제한손실 ${fmt(best.planned_risk_krw)}원 / 1회 허용 ${fmt(best.max_loss_krw)}원`}
function renderQuality(){const items=[...allResults.filter(x=>x.ok&&x.long_quality_candidate)].sort((a,b)=>Number(b.long_term?.score||0)-Number(a.long_term?.score||0)||Number(b.opportunity_score||0)-Number(a.opportunity_score||0)).slice(0,6),box=$('qualityCards'),empty=$('qualityEmpty');box.innerHTML='';if(!items.length){empty.style.display='block';empty.textContent='현재 기준을 통과한 장기 우량 후보가 없습니다.';return}empty.style.display='none';items.forEach((x,i)=>{const d=document.createElement('div');d.className='quality-mini';const lp=x.long_term||{};d.innerHTML=`<div><b>${i+1}. ${escapeText(x.name)}</b><span>${escapeText(x.long_quality_label||'💎 장기 우량 후보')}</span></div><strong>${lp.score||'-'}점 · ${lp.qty||0}주</strong><small>${escapeText(x.long_quality_reason||'')} · 장기예산 ${fmt(lp.budget_krw||0)}원</small>`;box.appendChild(d)})}
function renderSectorDashboard(data){
 const sa=data.sector_analysis||{},top=sa.top_sectors||[],box=$('sectorTop'),pickBox=$('sectorPickCards'),longBox=$('sectorLong'),holdBox=$('sectorHoldings'),warnBox=$('sectorWarnings');
 box.innerHTML=top.length?top.slice(0,5).map((x,i)=>`<div class="sector-rank"><div><b>${i+1}. ${escapeText(x.sector)}</b><span>${escapeText(x.label)} · ${x.score}점</span></div><small>5일 ${pct(x.avg_5d)} · RVOL ${x.avg_rvol}배 · 20일선 상단 ${x.breadth_pct}% · 매수후보 ${x.buy_count}개</small></div>`).join(''):'<div class="quality-empty">섹터 데이터가 부족합니다.</div>';
 pickBox.innerHTML=top.length?top.slice(0,5).map((sec,i)=>{const picks=sec.picks||[];return `<div class="sector-pick-group"><div class="sector-pick-head"><b>${i+1}. ${escapeText(sec.sector)}</b><span>${sec.score}점 · ${escapeText(sec.label)}</span></div>${picks.length?picks.map(p=>`<div class="sector-pick-item ${p.opportunity_eligible?'sector-pick-buy':''}"><span>${escapeText(p.role)}</span><b>${escapeText(p.name)}</b><em>${p.opportunity_eligible?'🔥 매수후보':'관찰'}</em><small>${escapeText(p.reason||'')} · 진입 ${fmt(p.entry_krw)}원 · ${escapeText(p.buy_time||'-')}</small></div>`).join(''):'<small>개별주 후보 부족</small>'}</div>`}).join(''):'<div class="quality-empty">섹터 추천 종목이 없습니다.</div>';
 const longMap={};allResults.filter(x=>x.ok&&x.long_quality_candidate).forEach(x=>{const s=x.sector||'기타';(longMap[s]||(longMap[s]=[])).push(x.name)});const longs=Object.entries(longMap).sort((a,b)=>b[1].length-a[1].length).slice(0,5);longBox.innerHTML=longs.length?longs.map(([s,n])=>`<div><b>${escapeText(s)}</b><span>${escapeText(n.slice(0,3).join(' · '))}</span></div>`).join(''):'현재 장기 우량 후보 없음';
 const alloc=sa.holding_allocation||[];holdBox.innerHTML=alloc.length?alloc.map(x=>`<div><b>${escapeText(x.sector)}</b><span>${x.weight_pct}% · ${fmt(x.value_krw)}원</span></div>`).join(''):'보유주 평단·수량 입력 시 표시';warnBox.innerHTML=(sa.concentration_warnings||[]).map(x=>`<div>${escapeText(x)}</div>`).join('');$('sectorNote').textContent='※ '+(sa.note||'현재 분석군 내부 상대 비교입니다.');
 const sf=$('sectorFilter'),prev=currentSector;sf.innerHTML='<option value="ALL">전체 섹터</option>'+[...new Set(allResults.filter(x=>x.ok).map(x=>x.sector||'기타'))].sort((a,b)=>a.localeCompare(b,'ko')).map(s=>`<option value="${escapeText(s)}">${escapeText(s)}</option>`).join('');if([...sf.options].some(o=>o.value===prev)){sf.value=prev}else{currentSector='ALL'}
}
function renderData(data,{restored=false}={}){allResults=data.results||[];$('marketState').textContent=data.market?.state||'데이터 없음';$('marketGuide').textContent=data.market?.guide||'';$('kospi').textContent=pct(data.market?.kospi_chg);$('kosdaq').textContent=pct(data.market?.kosdaq_chg);$('fx').textContent=fmt(data.summary?.usdkrw);$('recommended').textContent=data.summary?.individual_buyable_count??data.summary?.recommended??'-';$('etfBuyCount').textContent=data.summary?.etf_buyable_count??'-';$('scalpCount').textContent=data.summary?.scalp_count??'-';$('sCount').textContent=data.summary?.s_count??'-';$('aCount').textContent=data.summary?.a_count??'-';$('longQualityCount').textContent=data.summary?.long_quality_count??'-';$('totalCount').textContent=data.summary?.valid??'-';$('updatedAt').textContent=`마지막 분석: ${dateLabel(data.generated_at)}${restored?' · 저장된 결과':''}`;overallDecision();renderFinalAction(data);renderTopPick();renderBuyFocus();renderEtfFocus();renderScalpFocus(data);renderBudgetTop();renderPerformance();renderQuality();renderSectorDashboard(data);renderCards()}
function saveSnapshot(data){try{localStorage.setItem(SNAPSHOT_KEY,JSON.stringify(data))}catch(e){}}
function restoreSnapshot(){for(const key of [SNAPSHOT_KEY,...LEGACY_SNAPSHOT_KEYS]){try{const d=JSON.parse(localStorage.getItem(key)||'null');if(d&&Array.isArray(d.results)&&d.results.length){renderData(d,{restored:true});$('status').textContent='저장된 마지막 결과를 먼저 표시했습니다. 최신 분석을 자동으로 갱신합니다.';return true}}catch(e){}}return false}
