document.querySelectorAll('[data-trade]').forEach(btn=>btn.addEventListener('click',()=>{$('tradeBudget').value=btn.dataset.trade;saveSettings();updateMoneyNote()}));
['budget','tradeBudget','riskPct'].forEach(id=>$(id).addEventListener('input',()=>{saveSettings();updateMoneyNote()}));
async function analyze(){saveSettings();const btn=$('analyzeBtn');btn.disabled=true;btn.textContent='분석 중…';showInitialLoading();$('status').textContent=allResults.length?'저장 결과를 보여주는 동안 최신 시장·종목을 갱신 중입니다.':'빠른 스마트 분석 중입니다. 처음에는 10~30초 정도 걸릴 수 있습니다.';try{const headers={'Content-Type':'application/json'},pin=$('appPin').value.trim();if(pin)headers['X-App-Pin']=pin;const res=await fetch('/api/analyze',{method:'POST',headers,body:JSON.stringify(settingsPayload())});const data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||'분석 실패');annotateRankChanges(data);updateRecommendationHistory(data);renderData(data);saveSnapshot(data);saveRankBaseline(data);$('status').textContent=`분석 완료 · 정상 ${data.summary.valid}/${data.summary.total}개 · 분석군 ${data.summary.universe_size??data.summary.total}개 · ${data.summary.elapsed_sec}초${data.cache_hit?' · 캐시 사용':''}`}catch(e){showInitialError(e.message);$('status').textContent=`최신 분석 오류: ${e.message}${allResults.length?' · 저장된 결과를 유지합니다.':''}`}finally{btn.disabled=false;btn.textContent='최신 분석'}}
$('analyzeBtn').addEventListener('click',analyze);$('clearHistoryBtn').addEventListener('click',()=>{localStorage.removeItem(HISTORY_KEY);renderPerformance();$('status').textContent='추천 사후 성적표 기록을 삭제했습니다.'});$('clearSavedBtn').addEventListener('click',()=>{localStorage.removeItem(SNAPSHOT_KEY);allResults=[];$('cards').innerHTML='';$('topPick').hidden=true;$('noBuyCard').hidden=true;$('status').textContent='저장 결과를 삭제했습니다.'});
async function checkConnection(){try{const r=await fetch('/health',{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error();$('onlineState').textContent=`온라인 · ${d.version}`;$('onlineDot').classList.add('ok');$('connectionText').textContent=d.pin_required?'온라인 접속 · PIN 보호 사용 중':'온라인 접속 가능 · 홈 화면 추가 지원'}catch(e){$('onlineState').textContent='서버 연결 안 됨';$('onlineDot').classList.add('bad')}}
$('shareBtn').addEventListener('click',async()=>{const d={title:'V70.14.1 실전 검증 종목선별판',text:'최종 행동판 + 순위변화 + 추천 사후 성적표 + 위험기반 수량' ,url:location.href};try{if(navigator.share)await navigator.share(d);else{await navigator.clipboard.writeText(location.href);$('status').textContent='주소를 복사했습니다.'}}catch(e){}});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').classList.remove('hidden')});$('installBtn').addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installBtn').classList.add('hidden')});document.querySelectorAll('.bottom-nav button').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.action==='held'){activeFilter='HELD';document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x.dataset.filter==='HELD'));applyFilter();$('resultsSection').scrollIntoView({behavior:'smooth'});return}const el=$(btn.dataset.scroll);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}));
loadSettings();updateMoneyNote();const restored=restoreSnapshot();checkConnection();setTimeout(()=>analyze(),restored?1200:450);if('serviceWorker'in navigator)navigator.serviceWorker.register('/static/sw.js').catch(()=>{});
